<script setup lang="ts">
import {ref,onMounted,nextTick,watch,computed,onBeforeUnmount} from 'vue';
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,can:(p:string)=>boolean,initialReaderId?:number|null}>();
const emit=defineEmits<{readerConsumed:[]}>();
const modal=ref<HTMLElement|null>(null);let previousFocus:HTMLElement|null=null;
const newKey=()=>crypto.randomUUID();
const recent=ref<any[]>([]), late=ref<any[]>([]), searchingReader=ref(false);
const categoryNames:Record<string,string>={student:'Студент',teacher:'Преподаватель',staff:'Сотрудник',external:'Внешний читатель',other:'Другая категория'};
const debt=computed(()=>reader.value?.fines.reduce((sum:number,f:any)=>sum+Number(f.amount),0)||0);
const readerWarnings=computed(()=>{const r=reader.value;if(!r)return [];const w=[];if(r.status!=='active')w.push(r.block_reason||'Обслуживание читателя приостановлено');if(r.fines.length)w.push('Есть незакрытые штрафы');if(r.incidents.length)w.push('Есть открытые инциденты');if(r.overdue)w.push('Есть просроченные книги');if(r.used+basket.value.length>r.max_loans)w.push('Корзина превышает лимит');if(r.valid_until&&r.valid_until<new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty'}).format(new Date()))w.push('Срок билета истёк');return w;});
let readerTimer:ReturnType<typeof setTimeout>|undefined;
function readerTyping(){clearTimeout(readerTimer);searchingReader.value=false;readerSeq++;readerResults.value=[];if(readerQuery.value.trim().length>=2)readerTimer=setTimeout(searchReader,300);}
onBeforeUnmount(()=>{clearTimeout(readerTimer);readerSeq++;copySeq++;});
async function resetReader(){clearTimeout(readerTimer);searchingReader.value=false;readerSeq++;reader.value=null;readerQuery.value='';readerResults.value=[];basket.value=[];issued.value=[];found.value={items:[]};override.value=false;reason.value='';error.value='';success.value='';changed();await nextTick();readerInput.value?.focus();}
const notices=ref<any[]>([]);
const tab=ref('overview'),busy=ref(false),error=ref(''),success=ref(''),options=ref<any>({branches:[],policy:{}}),dashboard=ref<any>({}),reader=ref<any>(null);
const readerQuery=ref(''),readerResults=ref<any[]>([]),copyQuery=ref(''),found=ref<any>({items:[]}),basket=ref<any[]>([]),issued=ref<any[]>([]),returnLoan=ref<any>(null);
const history=ref<any>({items:[],total:0}),offset=ref(0),query=ref(''),status=ref(''),from=ref(''),to=ref(''),branch=ref(''),detail=ref<any>(null);
const dialog=ref<any>(null),settings=ref<any>(null),override=ref(false),reason=ref(''),codeInput=ref<HTMLInputElement|null>(null),readerInput=ref<HTMLInputElement|null>(null);
watch(()=>dialog.value,async(value)=>{if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();modal.value?.querySelector<HTMLElement>('input,select,textarea,button')?.focus();}else previousFocus?.focus();});
function trapFocus(event:KeyboardEvent){if(event.key!=='Tab')return;const nodes=Array.from(modal.value?.querySelectorAll<HTMLElement>('input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled])')||[]).filter(x=>x.offsetParent!==null);if(!nodes.length)return;if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0].focus();}}
let readerSeq=0,copySeq=0;const operationKey=ref(crypto.randomUUID());
const labels:Record<string,string>={active:'Выдана',overdue:'Просрочена',returned:'Возвращена',lost:'Утрачена',available:'Свободен',reserved:'Забронирован',on_loan:'На руках',repair:'В ремонте',processing:'На обработке',transfer:'В перемещении',display:'На выставке',reserve_stock:'Резервный фонд',withdrawn:'Списан',cancelled:'Отменено',unavailable:'Недоступен',queued:'В очереди',pending:'Требует проверки',confirmed:'Выделен экземпляр',ready_for_pickup:'Готово к получению',fulfilled:'Исполнено',expired:'Истёк срок',paid:'Оплачен',waived:'Освобождён',open:'Открыто',resolved:'Решено',damaged:'Повреждение',presumed_lost:'Предполагаемая утрата',issued:'Выдана',renewed:'Продлена',due_tomorrow:'Возврат завтра',reservation_ready:'Бронь готова',in_transit:'В пути'};
const conditions:Record<string,string>={unchanged:'Без изменений',good:'Пригодная',worn:'Обычный износ',minor:'Лёгкое повреждение',moderate:'Умеренное повреждение',severe:'Сильное повреждение',irreparable:'Неустранимое повреждение',lost:'Утрата'};
const dates=(v:string)=>v?new Date(v.endsWith('Z')||/[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('ru-RU',{timeZone:'Asia/Almaty'}):'—';
const day=(v:string)=>v?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty'}).format(new Date(v.endsWith('Z')||/[+-]\d\d:\d\d$/.test(v)?v:v+'Z')):'';
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=String(e);}finally{busy.value=false;}}
function changed(){operationKey.value=crypto.randomUUID();}
async function load(){
 if(tab.value==='overview'){dashboard.value=await props.api('/circulation/dashboard');if(props.can('circulation.view_any_history')){const [a,b]=await Promise.all([props.api('/circulation/loans?status=overdue'),props.api('/circulation/loans')]);late.value=a.items.slice(0,6);recent.value=b.items.slice(0,6);}}
 if(tab.value==='mine')notices.value=await props.api('/circulation/mine/notices');
 if(['history','reservations','fines','incidents','mine'].includes(tab.value)){
  const path=tab.value==='history'?'loans':tab.value;
  const params=new URLSearchParams({offset:String(offset.value),q:query.value,status:status.value});
  if(from.value)params.set('from_on',from.value);if(to.value)params.set('to_on',to.value);if(branch.value)params.set('branch_id',branch.value);
  history.value=await props.api('/circulation/'+path+'?'+params);
 }
 if(tab.value==='settings')settings.value=await props.api('/circulation/settings');
}
async function switchTab(value:string){tab.value=value;offset.value=0;status.value='';detail.value=null;returnLoan.value=null;found.value={items:[]};await run(load);await nextTick();if(value==='issue')readerInput.value?.focus();if(value==='return')codeInput.value?.focus();}
async function searchReader(){clearTimeout(readerTimer);if(!readerQuery.value.trim())return;const seq=++readerSeq;searchingReader.value=true;error.value='';try{const data=await props.api('/circulation/readers?'+new URLSearchParams({q:readerQuery.value}));if(seq!==readerSeq)return;readerResults.value=data.items;if(!data.items.length)error.value='Читатель не найден';}catch(e){if(seq===readerSeq)error.value=String(e);}finally{if(seq===readerSeq)searchingReader.value=false;}}
async function chooseReader(id:number){await run(async()=>{clearTimeout(readerTimer);readerSeq++;reader.value=await props.api('/circulation/readers/'+id);override.value=false;reason.value='';readerResults.value=[];basket.value=[];issued.value=[];changed();await nextTick();codeInput.value?.focus();});}
async function searchCopies(recordId?:number,copyOffset=0){const seq=++copySeq;error.value='';try{const params=recordId?'record_id='+recordId+'&offset='+copyOffset:new URLSearchParams({q:copyQuery.value}).toString();const data=await props.api('/circulation/copies?'+params);if(seq!==copySeq)return;found.value={...data,recordId,offset:copyOffset};if(!data.items.length)error.value='Совпадений не найдено';if(tab.value==='return'&&data.kind==='copies'&&data.items.length===1)await selectReturn(data.items[0]);}catch(e){if(seq===copySeq)error.value=String(e);}}
function addCopy(c:any){if(!reader.value){error.value='Сначала выберите читателя';return;}if(basket.value.some(x=>x.id===c.id)){error.value='Этот экземпляр уже в корзине';return;}basket.value.push({...c,due_on:c.suggested_on,reason:''});changed();copyQuery.value='';found.value={items:[]};nextTick(()=>codeInput.value?.focus());}
async function issue(){await run(async()=>{const result=await props.api('/circulation/issue','POST',{request_key:operationKey.value,reader_id:reader.value.id,items:basket.value.map(c=>({copy_id:c.id,due_on:c.due_on,reason:c.reason})),override:override.value,reason:reason.value});issued.value=result.loans;basket.value=[];changed();reader.value=await props.api('/circulation/readers/'+reader.value.id);success.value='Выдача оформлена';});}
async function selectReturn(c:any){if(!c.loan_id){error.value='У экземпляра нет открытой выдачи';return;}await run(async()=>{returnLoan.value=await props.api('/circulation/loans/'+c.loan_id);dialog.value={type:'return',id:returnLoan.value.id,version:returnLoan.value.version,condition:'unchanged',incident:'none',action:'none',notes:'',amount:'0',request_key:crypto.randomUUID()};});}
function renew(l:any){dialog.value={type:tab.value==='mine'?'own-renew':'renew',id:l.id,version:l.version,due_on:'',override:false,reason:'',request_key:crypto.randomUUID()};}
function reserve(c:any){if(!reader.value){error.value='Выберите читателя для бронирования';return;}dialog.value={type:'reserve',reader_id:reader.value.id,record_id:c.record_id,branch_id:null,request_key:crypto.randomUUID()};}
function action(type:string,item:any,action=''){dialog.value={type,id:item.id,version:item.version,action,reason:'',request_key:crypto.randomUUID()};}
function copySettings(c:any){dialog.value={...c.circulation,type:'copy',id:c.id,reason:'',request_key:crypto.randomUUID()};}
function setCondition(){const d=dialog.value;d.incident=d.condition==='lost'?'lost':['minor','moderate','severe','irreparable'].includes(d.condition)?'damaged':'none';d.action=d.incident==='damaged'?'repair':'none';if(d.incident==='none')d.amount='0';}
async function submitDialog(){await run(async()=>{const d=dialog.value;const {type,id,...body}=d;let path='';
 if(type==='return')path='/loans/'+id+'/return';
 if(type==='renew'||type==='own-renew'){path=(type==='own-renew'?'/mine/':'/loans/')+id+'/renew';if(!body.due_on)body.due_on=null;}
 if(type==='reserve')path='/reservations';
 if(type==='reservation')path='/reservations/'+id;
 if(type==='fine'){path='/fines/'+id;delete body.version;}
 if(type==='incident')path='/incidents/'+id;
 if(type==='limits'){path='/readers/'+id+'/limits';delete body.version;}
 if(type==='copy'){path='/copies/'+id;delete body.copy_id;delete body.issue_count;}
 const result=await props.api('/circulation'+path,'POST',body);dialog.value=null;success.value=type==='return'?(result.status==='lost'?'Утрата зафиксирована, физического возврата нет':'Книга возвращена'):'Операция сохранена';returnLoan.value=null;detail.value=null;found.value={items:[]};await load();if(reader.value)reader.value=await props.api('/circulation/readers/'+reader.value.id);
 });}
async function openDetail(id:number){await run(async()=>{detail.value=await props.api('/circulation/loans/'+id);});}
async function saveSettings(){await run(async()=>{settings.value=await props.api('/circulation/settings','POST',{...settings.value,request_key:operationKey.value});changed();success.value='Настройки сохранены';options.value=await props.api('/circulation/options');});}
const policyNames:Record<string,string>={max_loans:'Лимит выдач',scarce_max:'Верхний порог редких экземпляров',standard_max:'Верхний средний порог',scarce_days:'Срок редких книг, дней',standard_days:'Средний срок, дней',abundant_days:'Срок многочисленных книг, дней',manual_days:'Обычное окно ручной даты, дней',renewals_enabled:'Разрешить продление',max_renewals:'Число продлений',renewal_days:'Период продления, дней',block_overdue:'Запрет выдачи при просрочках',block_incidents:'Запрет выдачи при открытых делах',fine_per_day:'Штраф за день просрочки, ₸ (0 — отключён)',presumed_lost_days:'Предполагаемая утрата через дней (0 — отключена)',preparation_days:'Срок подготовки брони, дней',pickup_days:'Срок получения брони, дней',reservation_extensions:'Продлений брони',max_reservations:'Лимит броней'};
onMounted(()=>run(async()=>{const first=[['overview','circulation.issue'],['return','circulation.return'],['history','circulation.view_any_history'],['history','circulation.view_own_history'],['reservations','reservations.manage'],['fines','fines.manage'],['incidents','incidents.manage'],['settings','circulation.settings'],['mine','loans.view_own']].find(([,right])=>props.can(right));tab.value=first?.[0]||'overview';if(tab.value!=='mine')options.value=await props.api('/circulation/options');await load();if(props.initialReaderId&&props.can('circulation.issue')){tab.value='issue';reader.value=await props.api('/circulation/readers/'+props.initialReaderId);emit('readerConsumed');await nextTick();codeInput.value?.focus();}}));
</script>
<template>
<section class="circulation-page">
<header class="desk-heading"><div><h1>{{tab==='overview'?'Обслуживание читателей':tab==='issue'?'Выдача материала':tab==='return'?'Возврат материала':'Книговыдача'}}</h1><p>{{tab==='issue'?'Идентифицируйте читателя, проверьте ограничения и отсканируйте экземпляр.':'Выдача, возврат и продление материалов, контроль сроков и задолженностей.'}}</p></div><div class="heading-actions"><button v-if="tab!=='overview'&&can('circulation.issue')" @click="switchTab('overview')">← Назад</button><button v-if="tab!=='issue'&&can('circulation.issue')" class="primary" @click="switchTab('issue')">↥ Выдача материала</button><button v-if="tab!=='return'&&can('circulation.return')" @click="switchTab('return')">▣ Возврат материала</button></div></header>
<nav class="toolbar desk-tabs" aria-label="Разделы книговыдачи"><button v-for="[id,label,right] in [['overview','Обзор','circulation.issue'],['issue','Выдача','circulation.issue'],['return','Возврат','circulation.return'],['history','История','circulation.view_own_history'],['reservations','Брони','reservations.manage'],['fines','Штрафы','fines.manage'],['incidents','Инциденты','incidents.manage'],['settings','Настройки','circulation.settings'],['mine','Мои книги','loans.view_own']]" v-show="can(right)||(id==='history'&&can('circulation.view_any_history'))" :class="{primary:tab===id}" :disabled="busy" @click="switchTab(id)">{{label}}</button></nav>
<p v-if="error" class="error" role="alert">Не выполнено: {{error}}</p><p v-if="success" class="card" role="status">✓ {{success}}</p>
<div v-if="tab==='mine'&&notices.length" class="card"><h2>Уведомления в системе</h2><p v-for="n in notices">{{dates(n.created_at)}} · {{labels[n.kind]||n.kind}} · {{n.body.title||''}} {{n.body.due_at?dates(n.body.due_at):''}}</p><small>Email и SMS не подключены.</small></div>
<template v-if="tab==='overview'">
<div class="metrics"><article v-for="[key,label,icon] in [['open','Активные выдачи','▤'],['overdue','Просроченные','◷'],['issued_today','Выдано сегодня','↥'],['returned_today','Принято сегодня','▣'],['issued_week','Выдано за 7 дней','▦']]" class="metric"><div><span>{{label}}</span><span class="metric-icon" aria-hidden="true">{{icon}}</span></div><strong>{{dashboard[key]??'—'}}</strong></article></div>
<div v-if="can('circulation.view_any_history')" class="dashboard-grid"><article class="card dashboard-panel"><h2>Просроченные выдачи</h2><div class="table-scroll"><table><thead><tr><th>Читатель</th><th>Издание</th><th>Срок возврата</th><th>Просрочка</th></tr></thead><tbody><tr v-for="l in late"><td>{{l.reader_name}}</td><td>{{l.title}}<small>{{l.inventory_number}}</small></td><td>{{day(l.due_at)}}</td><td>{{-l.days_remaining}} дн.</td></tr></tbody></table></div><div v-if="!late.length" class="empty-state"><span class="empty-icon">✓</span><p>Просроченных выдач нет.</p></div></article><article class="card dashboard-panel"><h2>Последние выдачи</h2><div class="table-scroll"><table><thead><tr><th>Издание</th><th>Читатель</th><th>Статус</th></tr></thead><tbody><tr v-for="l in recent"><td>{{l.title}}<small>{{l.inventory_number}}</small></td><td>{{l.reader_name}}</td><td><span class="badge">{{labels[l.status]}}</span></td></tr></tbody></table></div><div v-if="!recent.length" class="empty-state"><span class="empty-icon">▤</span><p>Выдач пока нет.</p></div></article></div>
</template>
<article v-if="tab==='issue'||tab==='reservations'" class="card reader-step">
<h2 class="step-heading"><span class="step-number" :class="{complete:reader}">{{reader?'✓':'1'}}</span> Шаг 1. Читатель <span v-if="reader" class="badge positive">Выбран</span></h2>
<form v-if="!reader" class="reader-search" @submit.prevent="searchReader"><label for="circulation-reader">Поиск читателя</label><div class="search-control"><span aria-hidden="true">⌕</span><input id="circulation-reader" ref="readerInput" v-model="readerQuery" @input="readerTyping" :placeholder="can('readers.personal_data.view')?'ФИО, читательский билет, ИИН или email':'ФИО, читательский билет или email'" autocomplete="off" required aria-controls="reader-matches"><button :disabled="busy||searchingReader" aria-label="Найти читателя">{{searchingReader?'Поиск…':'Найти'}}</button></div><p class="help">Начните вводить — поиск идёт по имени, номеру билета и электронной почте. Сканер также можно использовать.</p>
<ul v-if="readerResults.length" id="reader-matches" class="reader-matches"><li v-for="r in readerResults" :key="r.id"><button type="button" :disabled="busy" @click="chooseReader(r.id)"><strong>{{r.full_name}}</strong><small>Читательский билет: {{r.ticket_number}} · {{categoryNames[r.category]||r.category}} · {{r.study_group||r.department}}</small></button></li></ul></form>
<div v-else class="reader-identity"><img v-if="reader.has_photo&&can('readers.registry.view')" :src="'/api/readers/'+reader.id+'/photo'" alt="Фото читателя" class="reader-avatar"><div v-else class="reader-avatar">{{reader.full_name[0]}}</div><div class="identity-name"><small>Читатель</small><strong>{{reader.full_name}}</strong><span>{{reader.study_group||reader.department}}</span></div><div><small>Читательский билет</small><strong>{{reader.ticket_number}}</strong></div><div><small>Категория</small><strong>{{categoryNames[reader.category]||reader.category}}</strong></div><div><small>Статус обслуживания</small><span class="badge" :class="{positive:reader.status==='active'}">{{reader.status==='active'?'✓ Активен':'Обслуживание приостановлено'}}</span></div><button :disabled="busy" @click="resetReader">⇄ Выбрать другого читателя</button></div>
</article>
<div v-if="tab==='issue'&&!reader" class="card empty-state reader-empty"><span class="empty-icon">♙</span><strong>Читатель не выбран. Найдите читателя, чтобы продолжить.</strong></div>
<div :class="{'issue-grid':tab==='issue'&&reader}">
<article v-if="tab==='issue'&&reader" class="card restrictions"><h2 class="step-heading"><span class="step-number" :class="{complete:!readerWarnings.length}">{{readerWarnings.length?'2':'✓'}}</span>Шаг 2. Проверка ограничений</h2><h3>Лимиты и ограничения</h3><div class="limit-cards"><div><small>МАТЕРИАЛЫ НА РУКАХ</small><strong>{{reader.used}} из {{reader.max_loans}}</strong><progress :value="reader.used" :max="reader.max_loans"></progress></div><div><small>ДОСТУПНО ПО ЛИМИТУ</small><strong>{{Math.max(0,reader.max_loans-reader.used-basket.length)}} экз.</strong></div><div><small>ЗАДОЛЖЕННОСТЬ</small><strong>{{debt.toLocaleString('ru-RU')}} ₸</strong></div></div><div class="restriction-notice" :class="{warning:readerWarnings.length}"><template v-if="readerWarnings.length"><strong>Обратите внимание</strong><ul><li v-for="w in readerWarnings">{{w}}</li></ul></template><template v-else>✓ По данным карточки ограничений не обнаружено.</template></div><p class="help">Окончательная проверка выполняется при подтверждении выдачи. Билет: {{reader.valid_until||'без срока'}}.</p><h3>Материалы на руках</h3><div v-if="!reader.loans.length" class="empty-inline">У читателя нет материалов на руках.</div><div v-for="l in reader.loans" class="held-book"><strong>{{l.title}}</strong><small>Инв. {{l.inventory_number}} · до {{day(l.due_at)}}</small><button v-if="can('circulation.renew')" :disabled="busy" @click="renew(l)">Продлить</button></div><details v-if="can('circulation.settings')" class="service-details"><summary>Обслуживание читателя</summary><button @click="dialog={type:'limits',id:reader.id,max_loans:reader.max_loans,reason:'',request_key:newKey()}">Индивидуальный лимит</button></details></article>
<div v-if="tab!=='issue'||reader" :class="{'card copy-step':tab==='issue'}"><h2 v-if="tab==='issue'" class="step-heading"><span class="step-number">3</span>Шаг 3. Экземпляр</h2>
<template v-if="['issue','return','reservations'].includes(tab)">
<form class="card toolbar" @submit.prevent="searchCopies()"><label>{{tab==='return'?'Сканировать возвращаемый экземпляр':'Штрихкод или инвентарный номер'}}<input ref="codeInput" v-model="copyQuery" @input="copySeq++" placeholder="Штрихкод, инвентарный номер или ISBN" required></label><button :disabled="busy">Найти экземпляр</button></form>
<div v-if="found.kind==='editions'" class="card"><p>{{found.message}}</p><button v-for="r in found.items" @click="searchCopies(r.id)">{{r.title}} — выбрать экземпляр</button></div>
<div v-if="found.kind==='copies'&&found.items.length" class="card table-scroll"><table><thead><tr><th>Книга / экземпляр</th><th>Местонахождение и состояние</th><th>Срок</th><th>Действия</th></tr></thead><tbody><tr v-for="c in found.items" :key="c.id"><td>{{c.title}}<br>{{c.author}}<br>Инв. {{c.inventory_number}} · {{c.barcode}}</td><td>{{c.branch||'Пункт не назначен'}}<br>{{labels[c.availability]||c.availability}} · {{conditions[c.circulation.condition]}}<br>{{c.circulation.access==='reading_room'?'Только читальный зал':c.circulation.access==='limited'?'Ограниченный доступ — проверьте условия':''}}</td><td>{{c.copy_count}} экз. → {{c.period_days}} дн.<br>{{c.suggested_on}}</td><td><button v-if="tab==='issue'" :disabled="busy||!reader" @click="addCopy(c)">В корзину</button><button v-if="tab==='return'" :disabled="busy" @click="selectReturn(c)">Принять возврат</button><button v-if="can('reservations.manage')&&reader" @click="reserve(c)">Забронировать издание</button><button v-if="can('circulation.copies')" @click="copySettings(c)">Состояние / пункт</button></td></tr></tbody></table><div v-if="found.recordId" class="toolbar"><button :disabled="!found.offset" @click="searchCopies(found.recordId,found.offset-50)">Назад</button><button :disabled="found.offset+50>=found.total" @click="searchCopies(found.recordId,found.offset+50)">Ещё экземпляры</button></div></div>
</template>
<div v-if="tab==='issue'" class="basket-section"><h3>Выдаваемые экземпляры <span class="badge">{{basket.length}}</span></h3><p class="help">Каждый экземпляр — отдельная строка со своим сроком возврата.</p><div v-if="!basket.length" class="empty-inline">Экземпляры ещё не добавлены.</div><form @submit.prevent="issue"><div v-for="(c,i) in basket" :key="c.id" class="basket-row"><strong>{{c.title}} · {{c.inventory_number}}</strong><label>Вернуть до<input v-model="c.due_on" type="date" required @change="changed"></label><label>Причина изменения срока<input v-model="c.reason" @input="changed"></label><button type="button" :disabled="busy" @click="basket.splice(i,1);changed()">Убрать</button></div><details v-if="can('circulation.override_limits')" class="override-panel"><summary>Выдать в обход ограничений</summary><label><input type="checkbox" v-model="override" @change="changed"> Разрешить исключение для лимита, просрочки или срока билета</label><label v-if="override">Обоснование<input v-model="reason" minlength="5" required @input="changed"></label></details><p class="help">Все экземпляры будут выданы одной операцией. При отказе корзина сохранится.</p><button class="primary" :disabled="busy||!basket.length">Подтвердить выдачу {{basket.length}} экз.</button></form></div>
<div v-if="issued.length&&tab==='issue'" class="card"><h2>Выдано</h2><p v-for="l in issued">{{l.title}} · {{l.inventory_number}} → {{dates(l.due_at)}}</p></div>
</div></div>
<template v-if="['history','mine','reservations','fines','incidents'].includes(tab)"><form class="card toolbar" @submit.prevent="offset=0;run(load)"><label v-if="tab==='history'||tab==='mine'">Поиск<input v-model="query" placeholder="Читатель или код экземпляра"></label><label>Статус<select v-model="status"><option value="">Все</option><option v-for="v in tab==='fines'?['pending','paid','waived']:tab==='incidents'?['open','resolved']:tab==='reservations'?['queued','pending','confirmed','ready_for_pickup','fulfilled','cancelled','expired']:['active','overdue','returned','lost']" :value="v">{{labels[v]}}</option></select></label><template v-if="tab==='history'"><label>Выдано с<input v-model="from" type="date"></label><label>По<input v-model="to" type="date"></label><label>Пункт<select v-model="branch"><option value="">Все</option><option v-for="b in options.branches" :value="String(b.id)">{{b.name}}</option></select></label></template><button :disabled="busy">Применить</button></form>
<div class="card"><p>Найдено: {{history.total}}</p><table><thead><tr><th>Книга / читатель</th><th>Состояние</th><th>Действия</th></tr></thead><tbody><tr v-for="r in history.items" :key="r.id"><td>{{r.title}}<br>{{r.reader_name}}<br>{{r.inventory_number||''}}</td><td>{{labels[r.status]||r.status}}<template v-if="tab==='history'||tab==='mine'"><br>Выдано {{dates(r.issued_at)}}<br>До {{dates(r.due_at)}}<br><span v-if="!r.closed_at">{{r.days_remaining===0?'Вернуть сегодня':r.days_remaining<0?'Просрочка: '+(-r.days_remaining)+' дн.':'Осталось: '+r.days_remaining+' дн.'}}</span></template><template v-if="tab==='reservations'"><br>Экземпляр: {{r.assigned_copy_id||'ожидается'}}<br>{{r.reason}}<br v-if="r.expires_at">{{r.expires_at?dates(r.expires_at):''}}</template><template v-if="tab==='fines'"><br>{{r.amount}} {{r.currency}} · {{labels[r.reason]}}<br>{{dates(r.charged_at)}}</template><template v-if="tab==='incidents'"><br>{{labels[r.kind]}} · {{r.description}}<br>{{r.decision}}</template></td><td><template v-if="tab==='history'||tab==='mine'"><button v-if="tab!=='mine'" @click="openDetail(r.id)">История операции</button><button v-if="!r.closed_at&&(can('circulation.renew')||tab==='mine'&&can('loans.renew_own'))" @click="renew(r)">Продлить</button></template><template v-if="tab==='reservations'&&['pending','queued','confirmed','ready_for_pickup'].includes(r.status)"><button v-if="r.status==='confirmed'" @click="action('reservation',r,'ready')">Готово к получению</button><button v-if="r.status==='pending'" @click="action('reservation',r,'retry')">Проверить повторно</button><button v-if="r.status==='ready_for_pickup'" @click="action('reservation',r,'extend')">Продлить бронь</button><button @click="action('reservation',r,'cancel')">Отменить</button></template><template v-if="tab==='fines'&&r.status==='pending'"><button @click="action('fine',r,'paid')">Отметить оплаченным</button><button v-if="can('fines.waive')" @click="action('fine',r,'waived')">Освободить</button></template><button v-if="tab==='incidents'&&r.status==='open'" @click="action('incident',r,'no_action')">Решение по делу</button></td></tr></tbody></table><div class="toolbar"><button :disabled="offset===0||busy" @click="offset-=50;run(load)">Назад</button><button :disabled="offset+50>=history.total||busy" @click="offset+=50;run(load)">Далее</button></div></div></template>
<div v-if="detail" class="card"><h2>{{detail.title}} · {{detail.inventory_number}}</h2><p>{{detail.reader_name}} · выдал {{detail.issued_by_name}} · принял {{detail.returned_to_name||'—'}}</p><p v-for="e in detail.events">{{dates(e.at)}} — {{labels[e.kind]||e.kind}} · {{e.previous_due?dates(e.previous_due)+' → ':''}}{{dates(e.new_due)}} · {{e.details.reason||e.details.override_reason}}</p><p v-for="c in detail.incidents">Дело №{{c.id}}: {{labels[c.kind]}} · {{labels[c.status]}} · {{c.description}}</p><button @click="detail=null">Закрыть историю</button></div>
<form v-if="tab==='settings'&&settings" class="card circulation-settings" @submit.prevent="saveSettings"><h2>Правила библиотеки</h2><label v-for="(label,key) in policyNames">{{label}}<input v-if="typeof settings.policy[key]==='boolean'" type="checkbox" v-model="settings.policy[key]" @change="changed"><input v-else v-model="settings.policy[key]" type="number" :step="key==='fine_per_day'?'0.01':'1'" min="0" @input="changed"></label><button :disabled="busy">Сохранить правила</button></form>
<div v-if="dialog" ref="modal" @keydown="trapFocus" class="circulation-overlay" role="dialog" aria-modal="true" aria-label="Подтверждение операции" @keydown.esc="!busy&&(dialog=null)"><form class="card" @submit.prevent="submitDialog"><h2>{{dialog.type==='return'?'Возврат / утрата':dialog.type.includes('renew')?'Продление':dialog.type==='reserve'?'Бронирование':dialog.type==='copy'?'Состояние экземпляра':'Подтверждение операции'}}</h2><p v-if="error" role="alert" class="error">{{error}}</p>
<template v-if="dialog.type==='return'"><p>{{returnLoan?.title}} · {{returnLoan?.reader_name}} · срок {{dates(returnLoan?.due_at)}}</p><label>Состояние<select v-model="dialog.condition" @change="setCondition"><option v-for="(label,key) in conditions" :value="key">{{label}}</option></select></label><p>Инцидент: {{dialog.incident==='none'?'Нет':labels[dialog.incident]}}</p><label v-if="dialog.incident==='damaged'">Предварительное действие<select v-model="dialog.action"><option value="repair">Ремонт</option><option value="replacement">Замена — до решения</option><option value="write_off">Списание — до решения</option><option value="return_to_fund">Вернуть в фонд</option><option value="fine">Штраф и возврат в фонд</option></select></label><label>Примечание<textarea v-model="dialog.notes" :required="dialog.incident!=='none'"></textarea></label><label v-if="dialog.incident!=='none'&&can('fines.manage')">Сумма за повреждение / утрату, ₸<input type="number" min="0" step="0.01" v-model="dialog.amount"></label><p>Выбор списания открывает дело; окончательный акт оформляется отдельно.</p></template>
<template v-if="dialog.type.includes('renew')"><label v-if="dialog.type!=='own-renew'">Новая дата (пусто — по правилам)<input type="date" v-model="dialog.due_on"></label><label v-if="can('circulation.override_limits')&&dialog.type!=='own-renew'"><input type="checkbox" v-model="dialog.override">Исключение по билету / просрочкам других книг</label></template>
<template v-if="dialog.type==='reserve'"><p>Бронь издания для {{reader?.full_name}}. Доступный экземпляр будет выделен в порядке очереди.</p><label>Пункт получения<select v-model="dialog.branch_id"><option :value="null">По месту экземпляра</option><option v-for="b in options.branches" :value="b.id">{{b.name}}</option></select></label></template>
<template v-if="dialog.type==='copy'"><label>Пункт<select v-model="dialog.branch_id"><option :value="null">Не назначен</option><option v-for="b in options.branches" :value="b.id">{{b.name}}</option></select></label><label>Физическое состояние<select v-model="dialog.condition"><option v-for="(label,key) in conditions" v-show="!['unchanged','lost'].includes(key)" :value="key">{{label}}</option></select></label><label>Доступность<select v-model="dialog.operation_state"><option value="normal">В обороте</option><option value="repair">Ремонт</option><option value="processing">Обработка</option><option value="transfer">Перемещение (недоступен)</option><option value="display">Выставка</option><option value="reserve_stock">Резервный фонд</option></select></label><label>Ограничение<select v-model="dialog.access"><option value="free">Свободно</option><option value="reading_room">Читальный зал</option><option value="limited">Ограниченный доступ</option></select></label><label>Дефекты<textarea v-model="dialog.defects"></textarea></label></template>
<label v-if="dialog.type==='limits'">Лимит открытых выдач<input type="number" min="1" max="500" v-model="dialog.max_loans" required></label><label v-if="dialog.type==='incident'">Решение<select v-model="dialog.action"><option value="no_action">Закрыть проверку с обоснованием</option><option value="repaired">Ремонт завершён</option><option value="found">Утраченная книга найдена</option><option value="written_off">Реальный акт списания уже оформлен</option><option value="replacement">Замена зарегистрирована, старый экземпляр списан</option></select></label>
<label v-if="!['return','reserve'].includes(dialog.type)">Причина / обоснование<textarea v-model="dialog.reason" :required="!dialog.type.includes('renew')" minlength="5"></textarea></label><div class="toolbar"><button class="primary" :disabled="busy">{{busy?'Сохранение…':'Подтвердить'}}</button><button type="button" :disabled="busy" @click="dialog=null">Отмена</button></div></form></div>
</section>
</template>
